import 'package:camera/camera.dart';
import 'package:flutter/cupertino.dart';
import 'package:flutter/material.dart';
import '../services/oil_color_service.dart';
import '../theme/app_theme.dart';

Future<void> openOilCheck(BuildContext context) => Navigator.of(context).push(MaterialPageRoute(builder: (_) => const OilCheckScreen()));
class OilCheckScreen extends StatefulWidget { const OilCheckScreen({super.key}); @override State<OilCheckScreen> createState()=>_OilCheckScreenState(); }
class _OilCheckScreenState extends State<OilCheckScreen> { CameraController? camera; OilColorResult? result; bool analyzing=false; String? error;
 @override void initState(){super.initState();_start();} Future<void> _start()async{try{final cams=await availableCameras();camera=CameraController(cams.first,ResolutionPreset.high,enableAudio:false);await camera!.initialize();if(mounted)setState((){});}catch(_){if(mounted)setState(()=>error='No pudimos abrir la cámara.');}}
 Future<void> _capture()async{if(camera==null||analyzing)return;setState(()=>analyzing=true);try{final image=await camera!.takePicture();final value=await OilColorService().analyze(image.path);if(mounted)setState(()=>result=value);}finally{if(mounted)setState(()=>analyzing=false);}}
 @override void dispose(){camera?.dispose();super.dispose();} @override Widget build(BuildContext context)=>Scaffold(backgroundColor:Colors.black,body:Stack(fit:StackFit.expand,children:[if(camera?.value.isInitialized==true)CameraPreview(camera!)else Center(child:error==null?const CircularProgressIndicator(color:AppTheme.teal):Text(error!,style:const TextStyle(color:Colors.white))),const DecoratedBox(decoration:BoxDecoration(gradient:LinearGradient(begin:Alignment.topCenter,end:Alignment.bottomCenter,colors:[Color(0x99000000),Colors.transparent,Color(0xCC000000)]))),SafeArea(child:Padding(padding:const EdgeInsets.all(22),child:Column(children:[Row(children:[IconButton.filledTonal(onPressed:()=>Navigator.pop(context),icon:const Icon(CupertinoIcons.xmark),style:IconButton.styleFrom(backgroundColor:Colors.black45,foregroundColor:Colors.white)),const SizedBox(width:10),const Text('PRUEBA DE ACEITE',style:TextStyle(color:Colors.white,fontWeight:FontWeight.w800,letterSpacing:1))]),const Spacer(),const _DipstickGuide(),const SizedBox(height:20),Text(result?.title??'Alinea la zona húmeda de la varilla',style:const TextStyle(color:Colors.white,fontSize:21,fontWeight:FontWeight.w800),textAlign:TextAlign.center),const SizedBox(height:8),Text(result?.guidance??'Limpia la varilla y colócala dentro del marco. Usa luz natural y evita reflejos.',style:const TextStyle(color:Colors.white70),textAlign:TextAlign.center),const SizedBox(height:22),if(result!=null)_ResultCard(result:result!),FilledButton.icon(onPressed:analyzing?null:_capture,style:FilledButton.styleFrom(backgroundColor:AppTheme.teal,minimumSize:const Size.fromHeight(54)),icon:analyzing?const SizedBox(width:20,height:20,child:CircularProgressIndicator(strokeWidth:2,color:Colors.white)):const Icon(CupertinoIcons.camera_fill),label:Text(analyzing?'Analizando color...':'Analizar color de aceite'))])))])); }
class _DipstickGuide extends StatelessWidget { const _DipstickGuide(); @override Widget build(BuildContext context)=>Container(width:280,height:170,decoration:BoxDecoration(color:Colors.black26,border:Border.all(color:const Color(0xFF66F0E4),width:3),borderRadius:BorderRadius.circular(28)),child:const Column(mainAxisAlignment:MainAxisAlignment.center,children:[Icon(CupertinoIcons.drop_fill,color:Color(0xFF66F0E4),size:42),SizedBox(height:8),Text('ZONA HÚMEDA',style:TextStyle(color:Colors.white,fontWeight:FontWeight.w800,letterSpacing:1.2)),SizedBox(height:4),Text('mantén la varilla centrada',style:TextStyle(color:Colors.white70,fontSize:12))])); }
class _ResultCard extends StatelessWidget { const _ResultCard({required this.result}); final OilColorResult result; @override Widget build(BuildContext context){final dark=result.appearance==OilAppearance.dark;final uncertain=result.appearance==OilAppearance.inconclusive;return Container(width:double.infinity,margin:const EdgeInsets.only(bottom:14),padding:const EdgeInsets.all(16),decoration:BoxDecoration(color:uncertain?const Color(0xFFFFF3D6):const Color(0xFFF1FFFB),border:Border.all(color:uncertain?Colors.orange:AppTheme.teal.withValues(alpha:.5)),borderRadius:BorderRadius.circular(22)),child:Row(children:[Icon(uncertain?CupertinoIcons.question_circle_fill:dark?CupertinoIcons.exclamationmark_triangle_fill:CupertinoIcons.check_mark_circled_solid,color:uncertain?Colors.orange:dark?Colors.deepOrange:Colors.green),const SizedBox(width:12),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(result.title,style:const TextStyle(color:Color(0xFF102B31),fontWeight:FontWeight.w800,fontSize:16)),const SizedBox(height:4),Text(result.guidance,style:const TextStyle(color:Color(0xFF30464A),fontWeight:FontWeight.w600,height:1.25)),const SizedBox(height:6),Text(result.confidenceLabel,style:const TextStyle(color:Color(0xFF52676B),fontSize:12,fontWeight:FontWeight.w700))]))]));}}
